import React from "react";
import { Routes, Route } from "react-router-dom";
import Header from "./components/Header";
import Footer from "./components/Footer";

import Home from "./components/Home";
import Admissions from "./components/Admissions";
import Academics from "./components/Academics";
import ExtraCurricular from "./components/ExtraCurricular";
import Download from "./components/Download";
import Gallery from "./components/Gallery";
import Contact from "./components/Contact";
import TheSchool from "./components/TheSchool";
import AdmissionForm from "./components/AdmissionForm";
import MandatoryDisclosure from "./components/MandatoryDisclosure";

// Layout for visitors/parents
import ParentDashboard from "./components/ParentDashboard";

// Admin-related components
import AdminLogin from "./components/AdminLogin";
import AdminDashboard from "./components/AdminDashboard";
import ViewAdmission from "./components/ViewAdmission";

export default function App() {
  return (
    <>
      <Header />

      <main className="main-wrapper">
        <Routes>
          {/* Home page stays normal */}
          <Route path="/" element={<Home />} />

          {/* 🧩 Wrap parent/visitor pages under ParentDashboard */}
          <Route path="/" element={<ParentDashboard />}>
            <Route path="academics" element={<Academics />} />
            <Route path="admissions" element={<Admissions />} />
            <Route path="extracurricular" element={<ExtraCurricular />} />
            <Route path="download" element={<Download />} />
            <Route path="gallery" element={<Gallery />} />
            <Route path="contact" element={<Contact />} />
            <Route path="school" element={<TheSchool />} />
            <Route path="admission-form" element={<AdmissionForm />} />
            <Route path="mandatory-disclosure" element={<MandatoryDisclosure />} />
          </Route>

          {/* Admin Routes */}
          <Route path="/admin/login" element={<AdminLogin />} />
          <Route path="/admin/dashboard" element={<AdminDashboard />} />
          <Route path="/admin/admission/:id" element={<ViewAdmission />} />
        </Routes>
      </main>

      <Footer />
    </>
  );
}
